 5	final class WeightedGraph implements Graph {
 6	    private static final int NO_EDGE = 0;
 7	
 8	    private final List<List<Neighbor>> neighborsByVertex;
 9	
10	    private WeightedGraph(List<List<Neighbor>> neighborsByVertex) {
11	        this.neighborsByVertex = neighborsByVertex;
12	    }
13	
14	    static WeightedGraph fromAdjacencyMatrix(int[][] adjacencyMatrix) {
15	        validateMatrix(adjacencyMatrix);
16	        return new WeightedGraph(buildNeighbors(adjacencyMatrix));
17	    }
18	
19	    @Override
20	    public int vertexCount() {
21	        return neighborsByVertex.size();
22	    }
23	
24	    @Override
25	    public List<Neighbor> neighborsOf(int vertex) {
26	        return neighborsByVertex.get(vertex);
27	    }
28	
29	    private static void validateMatrix(int[][] adjacencyMatrix) {
30	        if (adjacencyMatrix == null || adjacencyMatrix.length == 0) {
31	            throw new IllegalArgumentException("Graph must contain at least one vertex.");
32	        }
33	
34	        for (int row = 0; row < adjacencyMatrix.length; row++) {
35	            if (adjacencyMatrix[row] == null || adjacencyMatrix[row].length != adjacencyMatrix.length) {
36	                throw new IllegalArgumentException("Graph must be a square adjacency matrix.");
37	            }
38	        }
39	
40	        for (int row = 0; row < adjacencyMatrix.length; row++) {
41	            if (adjacencyMatrix[row][row] != NO_EDGE) {
42	                throw new IllegalArgumentException("Graph diagonal must be zero.");
43	            }
44	
45	            for (int column = row + 1; column < adjacencyMatrix.length; column++) {
46	                if (adjacencyMatrix[row][column] != adjacencyMatrix[column][row]) {
47	                    throw new IllegalArgumentException("Graph must be undirected and symmetric.");
48	                }
49	            }
50	        }
51	    }
52	
53	    private static List<List<Neighbor>> buildNeighbors(int[][] adjacencyMatrix) {
54	        List<List<Neighbor>> neighborsByVertex = new ArrayList<>(adjacencyMatrix.length);
55	
56	        for (int row = 0; row < adjacencyMatrix.length; row++) {
57	            int[] copiedRow = Arrays.copyOf(adjacencyMatrix[row], adjacencyMatrix[row].length);
58	            List<Neighbor> neighbors = new ArrayList<>();
59	
60	            for (int column = 0; column < copiedRow.length; column++) {
61	                int edgeWeight = copiedRow[column];
62	                if (edgeWeight != NO_EDGE) {
63	                    neighbors.add(new Neighbor(column, edgeWeight));
64	                }
65	            }
66	
67	            neighborsByVertex.add(List.copyOf(neighbors));
68	        }
69	
70	        return List.copyOf(neighborsByVertex);
71	    }
72	}

